import React, { useState, useEffect } from 'react';
import { 
  Alert,
  AlertDescription 
} from '@/components/ui/alert';

const App = () => {
  const [contacts, setContacts] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    address: ''
  });
  const [showAlert, setShowAlert] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');
  const [editingId, setEditingId] = useState(null);

  useEffect(() => {
    fetchContacts();
  }, []);

  const fetchContacts = () => {
    const savedContacts = localStorage.getItem('contacts');
    if (savedContacts) {
      setContacts(JSON.parse(savedContacts));
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const showNotification = (message) => {
    setAlertMessage(message);
    setShowAlert(true);
    setTimeout(() => setShowAlert(false), 3000);
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.name || !formData.phone || !formData.email || !formData.address) {
      showNotification('Please fill in all fields');
      return;
    }

    const newContact = {
      id: editingId || Date.now().toString(),
      ...formData
    };

    if (editingId) {
      setContacts(prev => {
        const updated = prev.map(contact => 
          contact.id === editingId ? newContact : contact
        );
        localStorage.setItem('contacts', JSON.stringify(updated));
        return updated;
      });
      setEditingId(null);
      showNotification('Contact updated successfully!');
    } else {
      setContacts(prev => {
        const updated = [...prev, newContact];
        localStorage.setItem('contacts', JSON.stringify(updated));
        return updated;
      });
      showNotification('Contact created successfully!');
    }

    setFormData({
      name: '',
      phone: '',
      email: '',
      address: ''
    });
    setShowForm(false);
  };

  const handleEdit = (contact) => {
    setFormData({
      name: contact.name,
      phone: contact.phone,
      email: contact.email,
      address: contact.address
    });
    setEditingId(contact.id);
    setShowForm(true);
  };

  const handleDelete = (id) => {
    if (window.confirm('Are you sure you want to delete this contact?')) {
      setContacts(prev => {
        const updated = prev.filter(contact => contact.id !== id);
        localStorage.setItem('contacts', JSON.stringify(updated));
        return updated;
      });
      showNotification('Contact deleted successfully!');
    }
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-4xl">
      <h1 className="text-3xl font-bold text-center mb-8">Contact Management System</h1>

      {!showForm && (
        <button
          onClick={() => setShowForm(true)}
          className="mb-8 bg-blue-500 text-white px-6 py-2 rounded-lg hover:bg-blue-600 transition-colors w-full md:w-auto"
        >
          Create Contact
        </button>
      )}

      {showForm && (
        <div className="bg-gray-50 rounded-lg p-6 mb-8 shadow-sm">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-semibold">
              {editingId ? 'Edit Contact' : 'Create Contact'}
            </h2>
            <button
              onClick={() => {
                setShowForm(false);
                setEditingId(null);
                setFormData({
                  name: '',
                  phone: '',
                  email: '',
                  address: ''
                });
              }}
              className="text-gray-500 hover:text-gray-700"
            >
              ✕
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              placeholder="Name"
              className="w-full p-2 border rounded"
            />

            <input
              type="tel"
              name="phone"
              value={formData.phone}
              onChange={handleInputChange}
              placeholder="Phone"
              className="w-full p-2 border rounded"
            />

            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleInputChange}
              placeholder="Email"
              className="w-full p-2 border rounded"
            />

            <input
              type="text"
              name="address"
              value={formData.address}
              onChange={handleInputChange}
              placeholder="Address"
              className="w-full p-2 border rounded"
            />

            <button
              type="submit"
              className="w-full bg-green-500 text-white p-2 rounded hover:bg-green-600 transition-colors"
            >
              {editingId ? 'Update Contact' : 'Create Contact'}
            </button>
          </form>
        </div>
      )}

      {showAlert && (
        <Alert className="mb-4">
          <AlertDescription>{alertMessage}</AlertDescription>
        </Alert>
      )}

      <div>
        <h2 className="text-xl font-semibold mb-4">Contacts List</h2>
        <div className="space-y-4">
          {contacts.map(contact => (
            <div key={contact.id} className="bg-white p-4 rounded-lg shadow">
              <h3 className="font-semibold">{contact.name}</h3>
              <p>Phone: {contact.phone} | Email: {contact.email}</p>
              <p>Address: {contact.address}</p>
              <div className="mt-2 space-x-2">
                <button
                  onClick={() => handleEdit(contact)}
                  className="bg-blue-500 text-white px-4 py-1 rounded hover:bg-blue-600"
                >
                  Edit
                </button>
                <button
                  onClick={() => handleDelete(contact.id)}
                  className="bg-red-500 text-white px-4 py-1 rounded hover:bg-red-600"
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default App;
